import Foundation

struct City: Codable {
    let name: String
    let population: Int
}
let json = "{\"name\": \"Cupertino\", \"population\": 60000}".data(using: .utf8)!
let city = try! JSONDecoder().decode(City.self, from: json)
print(city.name)

import Foundation

struct Item: Codable {
    let id: Int
    let title: String
    enum CodingKeys: String, CodingKey {
        case id
        case title = "item_title"
    }
}
let json = "{\"id\": 1, \"item_title\": \"Notebook\"}".data(using: .utf8)!
let item = try! JSONDecoder().decode(Item.self, from: json)
print(item.title)

import Foundation

struct Score: Codable {
    let points: Int
}
let score = Score(points: 95)
let data = try! JSONEncoder().encode(score)
let string = String(data: data, encoding: .utf8)!
print(string.contains("points"))

import Foundation

struct UserProfile: Codable {
    let name: String
    let role: String
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.name = try container.decode(String.self, forKey: .name)
        self.role = try container.decodeIfPresent(String.self, forKey: .role) ?? "Member"
    }
}
let json = "{\"name\": \"Sam\"}".data(using: .utf8)!
let profile = try! JSONDecoder().decode(UserProfile.self, from: json)
print(profile.role)

import Foundation

struct Book: Codable {
    let title: String
    let pageCount: Int
}
let json = "{\"title\": \"Swift Guide\", \"page_count\": 300}".data(using: .utf8)!
let decoder = JSONDecoder()
decoder.keyDecodingStrategy = .convertFromSnakeCase
let book = try! decoder.decode(Book.self, from: json)
print(book.pageCount)

