import Foundation

struct Account: Codable {
    let accountId: Int
    let accountName: String

    enum CodingKeys: String, CodingKey {
        case accountId = "account_id"
        case accountName = "account_name"
    }
}
let json = "{\"account_id\": 500, \"account_name\": \"Savings\"}".data(using: .utf8)!
let account = try! JSONDecoder().decode(Account.self, from: json)
print("\(account.accountId): \(account.accountName)")

import Foundation

struct Movie: Codable {
    let title: String
    let rating: Double

    enum CodingKeys: String, CodingKey {
        case title
        case rating
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.title = try container.decode(String.self, forKey: .title)
        self.rating = try container.decodeIfPresent(Double.self, forKey: .rating) ?? 5.0
    }
}
let json = "{\"title\": \"Inception\"}".data(using: .utf8)!
let movie = try! JSONDecoder().decode(Movie.self, from: json)
print("\(movie.title): \(movie.rating)")
